package com.vaibhav.ediflow.order.api;
import com.vaibhav.ediflow.order.domain.*;import com.vaibhav.ediflow.order.repository.*;import org.springframework.data.domain.*;import org.springframework.data.web.PageableDefault;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.bind.annotation.*;import java.math.BigDecimal;import java.time.*;import java.util.*;
@RestController @RequestMapping("/api/v1/invoices") public class InvoiceQueryController {private final InvoiceRepository invoices;private final ProcessingEventRepository events;public InvoiceQueryController(InvoiceRepository i,ProcessingEventRepository e){invoices=i;events=e;}@GetMapping @Transactional(readOnly=true) public Page<Summary> list(@PageableDefault(size=20,sort="createdAt",direction=Sort.Direction.DESC)Pageable p){return invoices.findAll(p).map(Summary::from);}@GetMapping("/{id}")@Transactional(readOnly=true)public Detail get(@PathVariable UUID id){Invoice i=invoices.findById(id).orElseThrow(()->new NotFound("Invoice not found."));return Detail.from(i,events.findByEntityTypeAndEntityIdOrderByOccurredAt("INVOICE",id));}record Summary(UUID id,String invoiceNumber,String referencedPoNumber,InvoiceStatus status,BigDecimal totalAmount,Instant createdAt){static Summary from(Invoice i){return new Summary(i.getId(),i.getInvoiceNumber(),i.getReferencedPoNumber(),i.getStatus(),i.getTotalAmount(),i.getCreatedAt());}}record Detail(UUID id,String partnerCode,String invoiceNumber,LocalDate invoiceDate,String referencedPoNumber,InvoiceStatus status,BigDecimal totalAmount,List<Line> lines,List<OrderQueryController.History> history){static Detail from(Invoice i,List<ProcessingEvent> h){return new Detail(i.getId(),i.getPartner().getCode(),i.getInvoiceNumber(),i.getInvoiceDate(),i.getReferencedPoNumber(),i.getStatus(),i.getTotalAmount(),i.getLines().stream().map(l->new Line(l.getLineNumber(),l.getSku(),l.getQuantity(),l.getUnitPrice())).toList(),h.stream().map(OrderQueryController.History::from).toList());}}record Line(int lineNumber,String sku,BigDecimal quantity,BigDecimal unitPrice){} }
